R=Path(__file__).resolve().parents[2];I=R/'evaluation-inputs/selfreview';O=R/'evaluation/selfreview';sys.path.insert(0,str(R/'design/private'));import grader
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();put=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n');delivery=json.loads((I/'DELIVERY-SEAL.json').read_text());summaries={};verified={}
