 combined=comparison['combined'];tp=combined['TP'];fp=combined['FP'];unknown=combined['uncertain']+len(uncertain);den=tp+fp+unknown
 bounds=dict(scope='Conservative unresolved-claim false-discovery-share bounds over adjudicated plus unresolved claims; these are not the frozen conditional FDR, and unmapped qualitative findings may remain outside the selected universe.',lower=fp/den if den else 'N/A',upper=(fp+unknown)/den if den else 'N/A',adjudicated_claims=tp+fp,unresolved_claims=unknown,total=den)
