 sensitivity=dict(policy='Separate sensitivity panel; comparison.json remains the exact frozen-function result. No changed row, tolerance, expected value or reclassification.',raw_subresolution_matches=subresolution,established_natural_product_defect_TP=0,natural_product_defect_denominator=0,natural_product_defect_recall='N/A',business_current_recall='N/A: zero natural F rows',business_transition_recall='N/A: zero natural F rows',style_native_recall='N/A: zero natural F rows',repair_interpretation='Raw fixed-row F-to-P/F/U only. Even F-to-P for a subresolution bound does not establish a natural business/style defect repair.')
 put(out/'uncertainty-and-sensitivity.json',dict(ineligible_or_qualitative_count=len(uncertain),frozen_matching_uncertain=combined['uncertain'],conservative_bounds=bounds,numerical_resolution_sensitivity=sensitivity,original_only_limitations=['Only sealed original machine failures and eligible original manual confirmed findings were matched.','All root-executed original machine failures enter irrespective of model repetition.','Later source/repair narratives were not read and cannot backfill detection of any other state/aspect.','Original qualitative legibility concerns remain unconfirmed and outside the selected24-family truth universe.','No own-corpus images/observations were reopened; supplied original evidence-validation records are retained.','Classical FPR is N/A without a defined complete negative claim universe.']))
 summaries[alias]=dict(machine={k:comparison['machine'][k] for k in ['TP','FP','natural_failures','recall','conditional_FDR','uncertain']},manual={k:comparison['manual'][k] for k in ['TP','FP','natural_failures','recall','conditional_FDR','uncertain']},combined={k:combined[k] for k in ['TP','FP','natural_failures','recall','conditional_FDR','uncertain']},repair=comparison['repair'],ineligible_or_qualitative_count=len(uncertain),conservative_bounds=bounds,natural_product_defect_sensitivity=sensitivity)
